// Los eventos llegan como items (cada item = 1 evento)
const eventos = items.map(i => i.json);

// Recuperar rango solicitado (viene del nodo anterior, pero OJO:
// si Google Calendar te pisó el JSON, necesitas MERGE)
const solicitado = $json.solicitado;

if (!solicitado?.inicio || !solicitado?.fin) {
  throw new Error(
    `No encuentro solicitado.inicio/fin. Esto pasa porque Google Calendar reemplaza el JSON.
Solución: añade un MERGE entre Google Calendar y este Code.`
  );
}

const inicioSolicitado = new Date(solicitado.inicio);
const finSolicitado = new Date(solicitado.fin);

function haySolapamiento(inicioA, finA, inicioB, finB) {
  return inicioA < finB && finA > inicioB;
}

let conflicto = null;

for (const ev of eventos) {
  const iniRaw = ev?.start?.dateTime ?? ev?.start?.date;
  const finRaw = ev?.end?.dateTime ?? ev?.end?.date;
  if (!iniRaw || !finRaw) continue;

  const inicioEv = new Date(iniRaw);
  const finEv = new Date(finRaw);

  if (haySolapamiento(inicioSolicitado, finSolicitado, inicioEv, finEv)) {
    conflicto = {
      id: ev.id ?? null,
      summary: ev.summary ?? '(Sin título)',
      inicio: inicioEv.toISOString(),
      fin: finEv.toISOString(),
    };
    break;
  }
}

return [
  {
    json: {
      solicitado,
      disponible: conflicto === null,
      conflicto,
      total_eventos_evaluados: eventos.length,
    },
  },
];

return items.map(item => {

  const fechaStr = item.json.fecha;

  const start = new Date(fechaStr);
  const end = new Date(start.getTime() + 60 * 60 * 1000); // +1 hora

  // Función para formatear fecha YYYY-MM-DDTHH:mm:ss
  function formatDate(date) {
    const pad = (num) => num.toString().padStart(2, '0');

    return (
      date.getFullYear() + '-' +
      pad(date.getMonth() + 1) + '-' +
      pad(date.getDate()) + 'T' +
      pad(date.getHours()) + ':' +
      pad(date.getMinutes()) + ':' +
      pad(date.getSeconds())
    );
  }

  item.json.start_time = formatDate(start);
  item.json.end_time = formatDate(end);

  return item;
});
